mapper.select:
select attendance_id, emp_id, work_date, check_in_at, check_out_at, status
from attendance
where emp_id = #{empId}
  and work_date = #{workDate}

select attendance_id, emp_id, work_date, check_in_at, check_out_at, status
from attendance
where emp_id = #{empId}
  and work_date between #{from} and #{to}
order by work_date

select e.emp_id, e.emp_no, e.ename, e.hiredate, e.status, d.department_id, d.department_name, d.department_level, d.parent_id, d.manager_id, j.job_id, j.job_name, j.job_level from emp e join department d on d.department_id = e.department_id join job j on j.job_id = e.job_id where e.status = 'ACTIVE' and e.hiredate <= #{to}
and e.department_id in #{deptId}
and (e.ename like concat('%', #{keyword}, '%') or e.emp_no like concat('%', #{keyword}, '%'))
order by case d.department_level when 1 then 0 when 2 then d.department_id else d.parent_id end, d.department_level, d.department_id, j.job_level desc, e.emp_id

select attendance_id, emp_id, work_date, check_in_at, check_out_at, status
from attendance
where work_date between #{from} and #{to}
  and emp_id in
#{empId}

mapper.update:
update attendance
set check_in_at = #{checkInAt},
    check_out_at = #{checkOutAt},
    status = #{status}
where attendance_id = #{attendanceId}

update attendance
set check_in_at = #{checkInAt},
    status = #{status}
where attendance_id = #{attendanceId}
  and check_in_at is null

update attendance
set check_out_at = #{checkOutAt},
    status = #{status}
where attendance_id = #{attendanceId}
  and check_out_at is null
